return ['domain'=>'capabilities-pro|| n % 10 == 6 || n % 10 == 9);|| n % 10 == 6 || n % 10 == 9);:','plural-forms'=>'nplurals=2; plural=n != 1 && n != 2 && n != 3 && (n % 10 == 4 || n % 10 == 6 || n % 10 == 9);','language'=>'fil','project-id-version'=>'PublishPress Capabilities Pro 2.13.0','pot-creation-date'=>'2026-03-03 12:30+0000','po-revision-date'=>'2026-09-22 14:15+0000','x-generator'=>'Loco https://localise.biz/','messages'=>['PublishPress Capabilities Pro'=>'PublishPress Capabilities Pro','https://publishpress.com/'=>'https://publishpress.com/','PublishPress Capabilities is the access control plugin for WordPress. You can manage all your WordPress user roles, from Administrators to Subscribers.'=>'Ang PublishPress Capabilities ay ang plugin para sa kontrol ng access para sa WordPress. Maaari mong pamahalaan ang lahat ng iyong mga tungkulin ng gumagamit sa WordPress, mula sa mga Administrator hanggang sa mga Subscriber.','PublishPress'=>'PublishPress','Note: Control of custom post statuses is %1$sdisabled%2$s.'=>'Tandaan: Ang kontrol ng mga custom na estado ng post ay %1$sna-disable%2$s.','Note: Status-specific post editing capabilities are %1$sdisabled%2$s.'=>'Tandaan: Ang kakayahan sa pag-edit ng post na tiyak sa estado ay %1$sna-disable%2$s.','Admin Menus'=>'Mga Admin Menu','Admin Menus allows you to edit the admin menu links and control who has access.'=>'Ang mga Admin Menu ay nagbibigay-daan sa iyo upang i-edit ang mga link ng admin menu at kontrolin kung sino ang may access.','You do not have permission to manage menu restrictions.'=>'Wala kang pahintulot na pamahalaan ang mga paghihigpit sa menu.','Settings updated for all roles.'=>'Na-update ang mga setting para sa lahat ng papel.','Settings updated.'=>'Na-update ang mga setting.','Saving Menu Order...'=>'Nagsasave ng Order ng Menu...','Saving Menu Name...'=>'Nagsasave ng Pangalan ng Menu...','Menu Name can not be empty.'=>'Hindi maaaring walang laman ang Pangalan ng Menu.','Change Icon'=>'Palitan ang Icon','Search icons...'=>'Naghahanap ng mga icon...','Menu icon updated'=>'Na-update ang menu icon','Error updating menu icon'=>'Error sa pag-update ng icon ng menu','Duplicate menu with this Menu URL already exists'=>'May umiiral nang duplicate na menu gamit ang Menu URL na ito','Duplicate submenu with the menu url already exist'=>'May umiiral nang duplicate na submenu gamit ang menu url','You do not have permission to manage settings.'=>'Wala kang pahintulot na pamahalaan ang mga setting.','Homepage'=>'Pahinang Pangunahing','Archive Pages'=>'Mga Archive na Pahina','Single Pages'=>'Mga Solitaryong Pahina','Select pages...'=>'Pumili ng mga pahina...','You can select page types where this element will be added.'=>'Maaari mong piliin ang mga uri ng pahina kung saan idadagdag ang elementong ito.','Select post types...'=>'Pumili ng mga uri ng post...','This will add a metabox on the post editing screen. You can use this feature to add body classes only for that post.'=>'Ito ay magdadagdag ng metabox sa screen ng pag-edit ng post. Maaari mong gamitin ang tampok na ito upang magdagdag ng mga klase ng katawan para lamang sa post na iyon.','Visibility Statuses'=>'Mga Katayuan ng Visibility','Visibility Status Capabilities'=>'Kakayahan sa Katayuan ng Visibility','Set'=>'Itakda','Read'=>'Bumasa','Edit Others'=>'I-edit ang Iba','Delete Others'=>'Tanggalin ang Iba','Can set posts to this status'=>'Maaaring itakda ang mga post sa status na ito','Can read posts in this status'=>'Maaaring basahin ang mga post sa status na ito','Can edit other users\' posts in this status'=>'Maaaring i-edit ang mga post ng ibang mga gumagamit sa status na ito','Can delete other users\' posts in this status'=>'Maaaring tanggalin ang mga post ng ibang mga gumagamit sa status na ito','Configure post status properties, post types'=>'I-configure ang mga katangian ng post status, mga uri ng post','Toggle all capabilities for this status'=>'I-toggle lahat ng kakayahan para sa katayuang ito','%s: assigned by Permission Group'=>'%s: itinalaga ng Permission Group','This capability is %s'=>'Ang kakayahang ito ay %s','It is required in addition to the type-specific capability.'=>'Kinakailangan ito bilang karagdagan sa kakayahan na partikular sa uri.','shared capability: %s'=>'naibahaging kakayahan: %s','Custom Statuses'=>'Mga Custom na Status','Revision Statuses'=>'Mga Estado ng Rebisyon','Revision Status Capabilities'=>'Kakayahan sa Estado ng Rebisyon','Custom Status Capabilities'=>'Mga Kakayahan ng Custom Status','Can edit posts of this status'=>'Maaaring i-edit ang mga post sa status na ito','Can edit other\'s posts of this status'=>'Maaaring i-edit ang mga post ng iba sa status na ito','Can delete posts of this status'=>'Maaaring tanggalin ang mga post sa status na ito','Can delete other\'s posts of this status'=>'Maaaring tanggalin ang mga post ng iba sa status na ito','Configure status properties, post types, capability requirements'=>'I-configure ang mga katangian ng status, mga uri ng post, mga kinakailangan sa kakayahan','To control revision editing and deletion, install the %1$sPublishPress Revisions%2$s and %3$sStatuses Pro%4$s plugins.'=>'Upang kontrolin ang pag-edit at pagtanggal ng bersyon, i-install ang %1$sPublishPress Revisions%2$s at %3$sStatuses Pro%4$s plugins.','To define and control Revision statuses, install the %1$sStatuses Pro%2$s plugin.'=>'Upang itakda at kontrolin ang mga katayuan ng Bersyon, i-install ang %1$sStatuses Pro%2$s na plugin.','To define and control Revision statuses, install the %1$sPublishPress Revisions%2$s plugin.'=>'Upang itakda at kontrolin ang mga katayuan ng Bersyon, i-install ang %1$sPublishPress Revisions%2$s na plugin.','To define and control Revision statuses, update the %1$sPublishPress Revisions%2$s plugin to version %3$s or higher.'=>'Upang itakda at kontrolin ang mga katayuan ng Bersyon, i-update ang %1$sPublishPress Revisions%2$s na plugin sa bersyon %3$s o mas mataas.','To control revision editing and deletion, p